INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (18, 'Mud Loss (Partial Loss of 45 bbl)', 2860.0, 2818.5, 'Formation-X', 'HIGH', 'Permeable sub-seismic micro-fracture network with lower fracture gradient.', 'Mixed and pumped 30 bbl medium/coarse walnut shell LCM pill; throttled flow rate from 2250 to 1950 LPM until returns stabilized.', 'Review offset fracture gradient before drilling ahead', 'WCR-OIL-DEMO-018', 37);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (21, 'Torque Spike & Pack-Off Flutter', 2842.0, 2802.0, 'Formation-X', 'HIGH', 'Interbedded brittle shale breakout causing cuttings bed accumulation in 32 deg inclination section.', 'Picked up off bottom, circulated high-viscosity pill, reciprocated drill string, executed short wiper trip to shoe.', 'Review offset fracture gradient before drilling ahead', 'DDR-OIL-DEMO-021', 22);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (11, 'Mud Loss (Seepage Loss of 20 bbl)', 2828.0, 2795.0, 'Formation-X', 'MODERATE', 'High overbalance pressure against depleted reservoir pressure.', 'Spotted fine calcium carbonate pill (25 ppb) in active system; reduced mud weight from 1.25 to 1.21 SG.', 'Review offset fracture gradient before drilling ahead', 'Mud Report-OIL-DEMO-011', 15);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (7, 'Differential Stuck Pipe', 2872.0, 2835.0, 'Formation-X', 'CRITICAL', 'High filter cake thickness combined with 450 psi hydrostatic overbalance.', 'Worked pipe with hydraulic jars (70 klbf up-blow); spotted 40 bbl oil-based pipe-freeing soak pill. Freed after 9.5 hrs.', 'Review offset fracture gradient before drilling ahead', 'WCR-OIL-DEMO-007', 42);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (1, 'Differential Sticking Alert', 1253.5, 1235.6, 'Girujan Clay Formation', 'MODERATE', 'Overbalanced mud column in depleted sand', 'Added lubricant to active mud system', 'Review offset fracture gradient before drilling ahead', 'WCR-OIL-DEMO-001', 41);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (1, 'Torque Spike & Drag', 1632.3, 1587.2, 'Girujan Clay Formation', 'MODERATE', 'Wellbore spiraling and tight hole', 'Short wiper trip and hole conditioning', 'Review offset fracture gradient before drilling ahead', 'WCR-OIL-DEMO-001', 14);
INSERT INTO public.drilling_events (well_id, event_type, depth_md_m, depth_tvd_m, formation_name, severity, primary_cause, immediate_mitigation, preventative_recommendation, source_document_name, source_page_number) VALUES (1, 'Gas Kick (Swab Gas)', 954.0, 923.7, 'Dhekiajuli Formation', 'HIGH', 'Swabbing effect during tripping', 'Circulated out bottoms up through choke manifold', 'Review offset fracture gradient before drilling ahead', 'WCR-OIL-DEMO-001', 64);
